import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.BbQrW5_t.js";const b=JSON.parse('{"title":"《AI Agent 实战》Chapter 1 核心知识点笔记","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/01-chapter1.md","filePath":"study/ai-agent-book/01-chapter1.md","lastUpdated":1785465991000}'),n={name:"study/ai-agent-book/01-chapter1.md"};function o(s,t,l,i,h,g){return r(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="《ai-agent-实战》chapter-1-核心知识点笔记" tabindex="-1">《AI Agent 实战》Chapter 1 核心知识点笔记 <a class="header-anchor" href="#《ai-agent-实战》chapter-1-核心知识点笔记" aria-label="Permalink to &quot;《AI Agent 实战》Chapter 1 核心知识点笔记&quot;">​</a></h1><hr><h2 id="一、agent-核心公式" tabindex="-1">一、Agent 核心公式 <a class="header-anchor" href="#一、agent-核心公式" aria-label="Permalink to &quot;一、Agent 核心公式&quot;">​</a></h2><h3 id="公式定义" tabindex="-1">公式定义 <a class="header-anchor" href="#公式定义" aria-label="Permalink to &quot;公式定义&quot;">​</a></h3><p><strong>Agent = LLM + 上下文 + 工具</strong></p><h3 id="直观理解" tabindex="-1">直观理解 <a class="header-anchor" href="#直观理解" aria-label="Permalink to &quot;直观理解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>直觉比喻</th><th>功能定位</th><th>学术概念</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>大脑</td><td>决策核心：理解意图、思考规划、做出判断</td><td>Policy（策略）</td></tr><tr><td><strong>上下文</strong></td><td>眼睛</td><td>感知信息：环境信息、用户记忆、领域知识、任务进展</td><td>Observation Space（观察空间）</td></tr><tr><td><strong>工具</strong></td><td>手脚</td><td>行动能力：感知、执行、协作、事件触发、用户沟通</td><td>Action Space（动作空间）</td></tr></tbody></table><h3 id="关键洞察" tabindex="-1">关键洞察 <a class="header-anchor" href="#关键洞察" aria-label="Permalink to &quot;关键洞察&quot;">​</a></h3><ul><li><strong>观察空间与动作空间 = LLM 与外部环境的接口</strong></li><li>没进入观察空间的信息，对模型&quot;不存在&quot;</li><li>没进入动作空间的操作，模型只能&quot;纸上谈兵&quot;</li><li><strong>在模型固定时，扩展上下文和工具是最主要的工程杠杆</strong></li></ul><hr><h2 id="二、工具体系-五大类型" tabindex="-1">二、工具体系（五大类型） <a class="header-anchor" href="#二、工具体系-五大类型" aria-label="Permalink to &quot;二、工具体系（五大类型）&quot;">​</a></h2><h3 id="工具分类" tabindex="-1">工具分类 <a class="header-anchor" href="#工具分类" aria-label="Permalink to &quot;工具分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>功能</th><th>典型示例</th></tr></thead><tbody><tr><td><strong>感知工具</strong></td><td>访问信息</td><td>搜索引擎、文件系统、API、数据库</td></tr><tr><td><strong>执行工具</strong></td><td>改变世界</td><td>代码执行、文件操作、系统命令、API调用</td></tr><tr><td><strong>协作工具</strong></td><td>分工合作</td><td>委托子Agent、人类确认、多Agent协调</td></tr><tr><td><strong>事件触发工具</strong></td><td>外部驱动</td><td>新邮件、定时任务、Webhook回调</td></tr><tr><td><strong>用户沟通工具</strong></td><td>信息传递</td><td>文字消息、语音通话、邮件</td></tr></tbody></table><h3 id="工具调用四步流程" tabindex="-1">工具调用四步流程 <a class="header-anchor" href="#工具调用四步流程" aria-label="Permalink to &quot;工具调用四步流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 声明工具（名称、用途、参数）</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>2. 模型自主决策（调不调、调哪个、传什么参数）</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>3. 执行工具，结果追加到上下文</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>4. 模型基于结果决定下一步</span></span></code></pre></div><h3 id="工具设计核心原则" tabindex="-1">工具设计核心原则 <a class="header-anchor" href="#工具设计核心原则" aria-label="Permalink to &quot;工具设计核心原则&quot;">​</a></h3><ul><li><strong>通用基础能力用于组合与探索</strong></li><li><strong>专用工具用于约束高风险和强业务规则操作</strong></li></ul><hr><h2 id="三、上下文结构" tabindex="-1">三、上下文结构 <a class="header-anchor" href="#三、上下文结构" aria-label="Permalink to &quot;三、上下文结构&quot;">​</a></h2><h3 id="上下文五层组成" tabindex="-1">上下文五层组成 <a class="header-anchor" href="#上下文五层组成" aria-label="Permalink to &quot;上下文五层组成&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>类型</th><th>功能</th></tr></thead><tbody><tr><td><strong>系统提示词</strong></td><td>静态前缀</td><td>Agent的&quot;岗位说明书&quot;，定义身份、权限、行为准则</td></tr><tr><td><strong>工具定义</strong></td><td>静态前缀</td><td>声明可用工具的名称、功能、参数格式</td></tr><tr><td><strong>用户消息</strong></td><td>动态轨迹</td><td>用户输入 + RAG检索的外部知识</td></tr><tr><td><strong>模型回复</strong></td><td>动态轨迹</td><td>reasoning（思考）+ content（回复）+ tool_calls（工具调用）</td></tr><tr><td><strong>工具执行结果</strong></td><td>动态轨迹</td><td>Agent下一步思考的直接依据</td></tr></tbody></table><h3 id="核心公式" tabindex="-1">核心公式 <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式&quot;">​</a></h3><p><strong>上下文 = 静态前缀（系统提示词 + 工具定义）+ 轨迹（动态消息历史）</strong></p><hr><h2 id="四、react-循环" tabindex="-1">四、ReAct 循环 <a class="header-anchor" href="#四、react-循环" aria-label="Permalink to &quot;四、ReAct 循环&quot;">​</a></h2><h3 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p><strong>ReAct = Reasoning + Acting</strong></p><h3 id="三环节循环" tabindex="-1">三环节循环 <a class="header-anchor" href="#三环节循环" aria-label="Permalink to &quot;三环节循环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>思考（Reasoning）→ 行动（Acting）→ 观察（Observing）→ 思考 → ...</span></span></code></pre></div><h3 id="轨迹-trajectory-结构" tabindex="-1">轨迹（Trajectory）结构 <a class="header-anchor" href="#轨迹-trajectory-结构" aria-label="Permalink to &quot;轨迹（Trajectory）结构&quot;">​</a></h3><ul><li>轨迹是Agent执行任务过程中积累的消息历史</li><li>每次LLM调用都看到<strong>完整轨迹</strong></li><li>轨迹具有累积性，保持Agent对任务的全局认知</li></ul><h3 id="多币种收入汇总示例-3次迭代" tabindex="-1">多币种收入汇总示例（3次迭代） <a class="header-anchor" href="#多币种收入汇总示例-3次迭代" aria-label="Permalink to &quot;多币种收入汇总示例（3次迭代）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1轮：分析任务 → 并行调用3个货币转换工具</span></span>
<span class="line"><span>第2轮：基于结果 → 调用代码解释器计算</span></span>
<span class="line"><span>第3轮：确认完成 → 生成最终答案</span></span></code></pre></div><hr><h2 id="五、agent-学习机制-三层次" tabindex="-1">五、Agent 学习机制（三层次） <a class="header-anchor" href="#五、agent-学习机制-三层次" aria-label="Permalink to &quot;五、Agent 学习机制（三层次）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>机制</th><th>时间尺度</th><th>特点</th></tr></thead><tbody><tr><td><strong>上下文适应</strong></td><td>任务内调整</td><td>即时</td><td>快速、低成本，受上下文窗口约束</td></tr><tr><td><strong>外部产物更新</strong></td><td>跨任务保留</td><td>持久</td><td>知识文档、Prompt/Skill、程序与Harness</td></tr><tr><td><strong>参数更新</strong></td><td>模型后训练</td><td>长期</td><td>部署成本高，形成广泛泛化能力</td></tr></tbody></table><p><strong>三条路径协同工作</strong>：上下文负责临场适应，外部产物负责可控积累，参数负责内化隐式能力。</p><hr><h2 id="六、harness-工程" tabindex="-1">六、Harness 工程 <a class="header-anchor" href="#六、harness-工程" aria-label="Permalink to &quot;六、Harness 工程&quot;">​</a></h2><h3 id="扩展公式" tabindex="-1">扩展公式 <a class="header-anchor" href="#扩展公式" aria-label="Permalink to &quot;扩展公式&quot;">​</a></h3><p><strong>Agent = LLM + [上下文 + 工具 + 约束 + 验证 + 纠正] = Model + Harness</strong></p><h3 id="harness-五要素" tabindex="-1">Harness 五要素 <a class="header-anchor" href="#harness-五要素" aria-label="Permalink to &quot;Harness 五要素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>职责</th><th>核心原则</th></tr></thead><tbody><tr><td><strong>上下文</strong></td><td>提供感知信息</td><td>信息充分性：每个决策点基于足够信息</td></tr><tr><td><strong>工具</strong></td><td>提供行动手段</td><td>接口清晰：命名直观、参数有例子、边界有说明</td></tr><tr><td><strong>约束</strong></td><td>设定行为边界</td><td>故障安全默认值：默认关闭，显式开放</td></tr><tr><td><strong>验证</strong></td><td>判断结果对错</td><td>输入隔离：检查结构化数据，不信任自由文本</td></tr><tr><td><strong>纠正</strong></td><td>自动修正恢复</td><td>中间态不暴露：静默重试，失败后回退</td></tr></tbody></table><h3 id="核心洞察" tabindex="-1">核心洞察 <a class="header-anchor" href="#核心洞察" aria-label="Permalink to &quot;核心洞察&quot;">​</a></h3><blockquote><p><strong>模型能力商品化，竞争优势转移到模型之外的工程实践</strong></p></blockquote><hr><h2 id="七、工程范式演进" tabindex="-1">七、工程范式演进 <a class="header-anchor" href="#七、工程范式演进" aria-label="Permalink to &quot;七、工程范式演进&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>软件工程 → 提示工程 → 上下文工程 → Harness工程 → Loop工程 → Graph工程</span></span></code></pre></div><p><strong>层层包含关系</strong>：后者包含前者，每层扩展工程师的关注范围。</p><hr><h2 id="八、编排模式对比" tabindex="-1">八、编排模式对比 <a class="header-anchor" href="#八、编排模式对比" aria-label="Permalink to &quot;八、编排模式对比&quot;">​</a></h2><h3 id="工作流模式-workflow" tabindex="-1">工作流模式（Workflow） <a class="header-anchor" href="#工作流模式-workflow" aria-label="Permalink to &quot;工作流模式（Workflow）&quot;">​</a></h3><ul><li><strong>特点</strong>：预定义代码路径，确定性执行</li><li><strong>优势</strong>：严格流程控制、高安全性</li><li><strong>局限</strong>：缺乏变通性</li><li><strong>适用</strong>：关键流程、合规要求严格的场景</li></ul><h3 id="自主agent模式-autonomous-agent" tabindex="-1">自主Agent模式（Autonomous Agent） <a class="header-anchor" href="#自主agent模式-autonomous-agent" aria-label="Permalink to &quot;自主Agent模式（Autonomous Agent）&quot;">​</a></h3><ul><li><strong>特点</strong>：动态决策执行路径，根据环境反馈实时调整</li><li><strong>核心能力</strong>：自主规划、识别失败、调整策略</li><li><strong>必须设计</strong>：明确的停止条件</li><li><strong>适用</strong>：开放式问题、步骤数不可预测的任务</li></ul><h3 id="选择原则" tabindex="-1">选择原则 <a class="header-anchor" href="#选择原则" aria-label="Permalink to &quot;选择原则&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>优化提示词 → 考虑工作流 → 最后才引入自主Agent</span></span></code></pre></div><hr><h2 id="九、护栏体系" tabindex="-1">九、护栏体系 <a class="header-anchor" href="#九、护栏体系" aria-label="Permalink to &quot;九、护栏体系&quot;">​</a></h2><h3 id="三层防护" tabindex="-1">三层防护 <a class="header-anchor" href="#三层防护" aria-label="Permalink to &quot;三层防护&quot;">​</a></h3><table tabindex="0"><thead><tr><th>防护位置</th><th>护栏类型</th><th>功能</th></tr></thead><tbody><tr><td><strong>输入侧</strong></td><td>相关性分类器</td><td>标记偏离主题的查询</td></tr><tr><td></td><td>安全分类器</td><td>检测越狱、提示注入</td></tr><tr><td></td><td>内容审核</td><td>标记有害内容</td></tr><tr><td></td><td>基于规则保护</td><td>黑名单、长度限制、正则过滤</td></tr><tr><td><strong>执行侧</strong></td><td>工具风险评级</td><td>低/中/高风险分级，高风险需额外审查</td></tr><tr><td><strong>输出侧</strong></td><td>PII过滤器</td><td>审查个人身份信息</td></tr><tr><td></td><td>输出验证</td><td>确保回复与品牌价值一致</td></tr></tbody></table><h3 id="人工干预触发条件" tabindex="-1">人工干预触发条件 <a class="header-anchor" href="#人工干预触发条件" aria-label="Permalink to &quot;人工干预触发条件&quot;">​</a></h3><ol><li><strong>超过失败阈值</strong>：重试次数或操作次数超限</li><li><strong>高风险操作</strong>：敏感、不可逆、高风险操作</li></ol><hr><h2 id="十、模型选型要点" tabindex="-1">十、模型选型要点 <a class="header-anchor" href="#十、模型选型要点" aria-label="Permalink to &quot;十、模型选型要点&quot;">​</a></h2><h3 id="御三家-闭源模型" tabindex="-1">&quot;御三家&quot;闭源模型 <a class="header-anchor" href="#御三家-闭源模型" aria-label="Permalink to &quot;&quot;御三家&quot;闭源模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>厂商</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Anthropic（Claude）</strong></td><td>复杂推理、编程、工具调用突出</td><td>Agent开发首选</td></tr><tr><td><strong>Google（Gemini）</strong></td><td>超长上下文、强大多模态</td><td>长文本、图片视频场景</td></tr><tr><td><strong>OpenAI（GPT/o）</strong></td><td>能力均衡，用户最多</td><td>通用场景</td></tr></tbody></table><h3 id="国内模型" tabindex="-1">国内模型 <a class="header-anchor" href="#国内模型" aria-label="Permalink to &quot;国内模型&quot;">​</a></h3><ul><li><strong>豆包</strong>：国内延迟极低，适合实时交互</li><li><strong>Kimi</strong>：国内Agent能力较强</li><li><strong>Qwen/DeepSeek</strong>：开源模型，成本和可定制性优势</li></ul><h3 id="选型关键维度" tabindex="-1">选型关键维度 <a class="header-anchor" href="#选型关键维度" aria-label="Permalink to &quot;选型关键维度&quot;">​</a></h3><ol><li><strong>支持Reasoning</strong>：绝大多数Agent需要</li><li><strong>输出token速度</strong>：影响端到端延迟</li><li><strong>多模态能力</strong>：按需评估</li></ol><hr><h2 id="十一、agent产品矩阵分析" tabindex="-1">十一、Agent产品矩阵分析 <a class="header-anchor" href="#十一、agent产品矩阵分析" aria-label="Permalink to &quot;十一、Agent产品矩阵分析&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Agent产品</th><th>眼睛（感知）</th><th>手脚（行动）</th><th>策略</th></tr></thead><tbody><tr><td><strong>Cursor等Coding Agent</strong></td><td>需求文档、代码库、终端</td><td>内部思考、搜索、编辑、执行</td><td>增量开发→测试→调试</td></tr><tr><td><strong>Deep Research等搜索Agent</strong></td><td>网络、数据库、本地文件</td><td>思考、搜索、阅读、摘要</td><td>迭代深化研究</td></tr><tr><td><strong>Browser Use等操控Agent</strong></td><td>屏幕、浏览器、文件系统</td><td>思考、点击、输入、截图</td><td>视觉感知+操作验证</td></tr><tr><td><strong>豆包等手机助手</strong></td><td>手机屏幕、已安装App</td><td>思考、点击、滑动、打开App</td><td>意图理解+App操控</td></tr><tr><td><strong>Pine AI等办事Agent</strong></td><td>账户信息、知识库</td><td>思考、打电话、发邮件、填表</td><td>多步骤任务执行</td></tr></tbody></table><hr><h2 id="十二、核心公式汇总" tabindex="-1">十二、核心公式汇总 <a class="header-anchor" href="#十二、核心公式汇总" aria-label="Permalink to &quot;十二、核心公式汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公式</th><th>含义</th></tr></thead><tbody><tr><td>Agent = LLM + 上下文 + 工具</td><td>Agent内部组成</td></tr><tr><td>Agent = Model + Harness</td><td>工程实现视角</td></tr><tr><td>上下文 = 静态前缀 + 轨迹</td><td>上下文结构</td></tr><tr><td>Harness = 上下文 + 工具 + 约束 + 验证 + 纠正</td><td>生产级保障</td></tr></tbody></table><hr><h2 id="核心结论" tabindex="-1">核心结论 <a class="header-anchor" href="#核心结论" aria-label="Permalink to &quot;核心结论&quot;">​</a></h2><ol><li><strong>Agent = 大脑 + 眼睛 + 手脚</strong>，三者缺一不可</li><li><strong>扩展眼睛和手脚是最主要的能力杠杆</strong></li><li><strong>上下文是决定性因素</strong>：去掉任何组件都会导致系统退化</li><li><strong>Harness是竞争力所在</strong>：确保Agent&quot;可靠地做事&quot;</li><li><strong>编排模式选择</strong>：先优化提示词→再工作流→最后自主Agent</li><li><strong>安全是架构问题</strong>：从第一行代码就要考虑</li></ol><hr><h2 id="思考题要点" tabindex="-1">思考题要点 <a class="header-anchor" href="#思考题要点" aria-label="Permalink to &quot;思考题要点&quot;">​</a></h2><ol><li>模型、上下文、工具三者的能力权衡与场景依赖</li><li>ReAct循环的二次方成本问题与优化方向</li><li>&quot;模型即Agent&quot;与Harness工程的共存关系</li><li>Agent无限循环的检测与终止机制</li><li>工作流与自主Agent的混合设计</li><li>工具动态风险评估策略</li><li>人工干预的边界处理机制</li></ol><hr><p><em>笔记整理自《AI Agent 实战》Chapter 1</em></p>`,85)])])}const p=a(n,[["render",o]]);export{b as __pageData,p as default};
